mapper.sql:
FROM learn_task_assignment assignment JOIN learn_task task ON task.id = assignment.task_id LEFT JOIN sys_organization source_organization ON source_organization.id = assignment.source_organization_id JOIN sys_user reviewer ON reviewer.id = assignment.current_reviewer_id LEFT JOIN learn_task_pause active_pause ON active_pause.assignment_id = assignment.id AND active_pause.resumed_at IS NULL AND active_pause.expires_at > CURRENT_TIMESTAMP LEFT JOIN learn_task_checkin latest_checkin ON latest_checkin.assignment_id = assignment.id AND latest_checkin.submission_no = ( SELECT MAX(checkin_version.submission_no) FROM learn_task_checkin checkin_version WHERE checkin_version.assignment_id = assignment.id ) WHERE assignment.student_id = #{query.studentId}
AND assignment.source_type = #{query.sourceType}
AND assignment.scheduled_date = #{query.scheduledDate}

