mapper.select:
SELECT student_id
FROM learn_task_assignment
WHERE task_id = #{taskId}
  AND scheduled_date = #{scheduledDate}
ORDER BY student_id

SELECT 

ORDER BY assignment.scheduled_date DESC, assignment.created_at DESC, assignment.id DESC
LIMIT #{query.limit} OFFSET #{query.offset}

SELECT assignment.id
FROM learn_task_assignment assignment
WHERE assignment.id > #{afterId}
  AND assignment.current_status = 'IN_PROGRESS'
  AND assignment.due_at <= #{cutoff}
  AND NOT EXISTS (
      SELECT 1
      FROM learn_task_pause active_pause
      WHERE active_pause.assignment_id = assignment.id
        AND active_pause.resumed_at IS NULL
        AND active_pause.expires_at > #{cutoff}
  )
ORDER BY assignment.id
LIMIT #{limit}

SELECT id, student_id, version_no
FROM learn_task_assignment
WHERE id = #{id}
  AND current_status = 'IN_PROGRESS'
  AND due_at <= #{cutoff}
FOR UPDATE

mapper.update:
UPDATE learn_task_assignment
SET current_status = #{nextStatus},
    claimed_at = COALESCE(#{claimedAt, jdbcType=TIMESTAMP}, claimed_at),
    completed_at = CASE
        WHEN #{nextStatus} = 'COMPLETED' THEN #{transitionAt}
        WHEN #{expectedStatus} = 'COMPLETED' AND #{nextStatus} <> 'COMPLETED' THEN NULL
        ELSE completed_at
    END,
    last_transition_at = #{transitionAt},
    version_no = version_no + 1,
    updated_at = #{transitionAt}
WHERE id = #{id}
  AND current_status = #{expectedStatus}
  AND version_no = #{expectedVersion}

UPDATE learn_task_assignment
SET current_reviewer_id = #{nextReviewerId},
    last_transition_at = #{transitionAt},
    version_no = version_no + 1,
    updated_at = #{transitionAt}
WHERE id = #{id}
  AND current_reviewer_id = #{expectedReviewerId}
  AND version_no = #{expectedVersion}
  AND current_status = 'PENDING_REVIEW'
